#!/usr/bin/env bash
LIFE_MANAGER_REPO="${LIFE_MANAGER_REPO:-$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel 2>/dev/null)}"
[ -n "$LIFE_MANAGER_REPO" ] || { echo "LIFE_MANAGER_REPO could not be resolved" >&2; exit 2; }
export LIFE_MANAGER_REPO
export PATH="/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin:$HOME/.local/bin:$PATH"  # claude itself lives in ~/.local/bin (npm global install, not homebrew)
# capafy-loop-cli.sh — always-on Capafy money-loop claude-p session (copied from earn/clip). Detached tmux
# runs headless claude that registers a DAILY driver cron then idles; healthcheck restarts if dead/stale.
set -uo pipefail
SOCK="/tmp/anicca-capafy-loop-tmux.sock"; SESSION="anicca-capafy-loop"
CLAUDE="$(command -v claude || echo "$HOME/.local/bin/claude")"
STARTUP='You are the Anicca Capafy money-loop core (claude-p, self-improving + self-healing; money → Dais bank; human + main-agent NOT in this loop). FIRST call CronList; if no job whose prompt mentions capafy money loop exists, CronCreate cron="0 9 * * *" recurring=true durable=true prompt="ONE pass of the Capafy money loop. STEP0 SELF-HEAL: AUTH-DOWN means ONLY that GET https://api.capafy.ai/agent/account returns HTTP 401 — check THAT first; if it returns 200 the token is VALID and you must NOT re-login. The Capafy marketplace SEARCH endpoint (POST /agent/agents/search) is currently BROKEN server-side (returns 500, or a MISLEADING 401 that says token expired, even with a valid token), and re-login just returns the SAME stable am_sk_ api-key so it can NEVER fix a search error — therefore a search failure is NEVER auth-down and NEVER a reason to re-login, retry, or spiral. Only if /agent/account itself is 401: re-login via login-init → read OTP from $LIFE_MANAGER_GMAIL_ACCOUNT via gog gmail (needs GOG_KEYRING_PASSWORD sourced from $HOME/.local/state/life-manager/.env) → login-verify → write token into BOTH vendor/capafy-publisher/config.json and vendor/capafy-user/config.json. If $HOME/.local/state/life-manager/state/capafy-loop-selfheal-request.json exists, read+diagnose+fix then rm it; CAPAFY-LOOP-STALE/NEVER-RAN → run bash $LIFE_MANAGER_REPO/skills/capafy-autopublish/scripts/daily_loop.sh; verify heal clears then rm the json; if you cannot fix it in this pass, bash $LIFE_MANAGER_REPO/skills/self/self-fix.sh capafy \"<the exact blocker + a concrete fix hint>\" to spawn an autonomous Opus dev that actually edits+runs+verifies+commits the code fix (THAT is the self-heal — never just file an issue and wait), then rm the json. STEP1 MEASURE: bash $LIFE_MANAGER_REPO/skills/self/capafy-loop/loop.sh and read its STATE.md. STEP2 ACT (single highest-EV move toward real Capafy revenue; your judgment, no script): improve SUPPLY QUALITY by publishing ONE more competitive, honest, lint-clean listing. Market-search (reading a top seller to clone) is BEST-EFFORT enrichment ONLY: try it at most once, but Capafy search is currently server-broken so expect it to fail — if it errors, do NOT retry, re-login, or stop; proceed WITHOUT it using $LIFE_MANAGER_REPO/skills/capafy-autopublish/BEST_PRACTICES.md + the proven-profitable playbook + existing inventory. Then publish exactly ONE ready item by running the BOUNDED drainer: bash $LIFE_MANAGER_REPO/skills/capafy-autopublish/scripts/daily_loop.sh (fail-closed, self-limited, timeout-guarded). If the slot cap is full OR no inventory item is ready (skill dir + icon both present), that is a LEGITIMATE NO-OP — report it and finish the pass cleanly; never hang waiting. Do at most ONE thing. STEP3 VERIFY: only a real subscriber or a listing reaching status=4 counts — published alone is NOT revenue; record the observable in STATE.md. IF your ACT fails because of a code/automation bug (e.g. daily_loop.sh reports publish FAIL / drive_cp1.py isConfirmedSkills=0 / any tool error), that is NOT a stop and NOT a defer — immediately bash $LIFE_MANAGER_REPO/skills/self/self-fix.sh capafy \"publish pipeline broken: <paste the exact error>. Fix the publisher (likely drive_cp1.py brittle UI automation) so a real skill publishes.\" and note it in STATE.md. STEP4 REPORT: bash $LIFE_MANAGER_REPO/skills/report/loop-report.sh capafy \"<what you did + real metric>\" <success|failure|no-op> <usd or 0> \"<evidence url or none>\". FINALLY — ALWAYS, even on a clean no-op or a caught error — touch $HOME/.local/state/life-manager/state/.capafy-loop-last-pass to prove this pass completed (this is the liveness heartbeat; never leave it un-touched by hanging or spiraling). Blocker is not stop; a broken Capafy endpoint is not stop.". THEN run ONE pass now (same body). THEN stop and idle.'
status(){ tmux -S "$SOCK" has-session -t "$SESSION" 2>/dev/null && echo ALIVE || echo DEAD; }
case "${1:-}" in --status) status; exit 0;; --restart) tmux -S "$SOCK" kill-session -t "$SESSION" 2>/dev/null||true;; esac
if [ "${1:-}" != "--restart" ] && tmux -S "$SOCK" has-session -t "$SESSION" 2>/dev/null; then echo "capafy-loop already ALIVE"; exit 0; fi
STARTUP="${STARTUP} 重要な結果（数字・IDを含む成果、realized P&L、致命的エラー）が出たら PushNotification ツールで Dais へ verbatim 送信してから終了する。narration・定常報告には使わない。"
# Auth: launchd/tmux cannot refresh the subscription OAuth token headlessly (keychain locked) —
# same fallback already proven live by gig-cli.sh / gig_reality_verify.sh — route through the
# local CLIProxyAPI (:8317) whose creds are plain files and refresh headlessly; fall back to
# subscription auth if the key file is absent.
CLIPROXY_KEY="$(cat "$HOME/.cli-proxy-api-key" 2>/dev/null || true)"
if [ -n "$CLIPROXY_KEY" ]; then
  export ANTHROPIC_BASE_URL="http://127.0.0.1:8317"
  export ANTHROPIC_AUTH_TOKEN="$CLIPROXY_KEY"
fi
tmux -S "$SOCK" new-session -d -s "$SESSION" "$CLAUDE" --name "$SESSION" --model sonnet --dangerously-skip-permissions --add-dir "$HOME" -- "$STARTUP"
mkdir -p "$HOME/.local/state/life-manager/state" && touch "$HOME/.local/state/life-manager/state/.capafy-loop-last-start"; sleep 2
echo "capafy-loop started ($(status))."
